- A rows are emitted for every hard preassignment; omitted nurse-days are rest.", "solve_py": "#!/usr/bin/env python3
"""Nurse rostering W7-01 multi-skill solver (PySCIPOpt)."""
import csv
import json
import os
import sys

from pyscipopt import Model, quicksum

DATA = "/app/data"
OUT = "/app/submissions/solution.csv"
MODEL_MD = "/app/submissions/model.md"
LOG_MD = "/app/submissions/solve_log.md"

def read_csv(name):
    with open(os.path.join(DATA, name), newline="") as f:
        return list(csv.DictReader(f))

def main():
    days = read_csv("days.csv")
    shifts = read_csv("shifts.csv")
    skills = read_csv("skills.csv")
    contracts = read_csv("contracts.csv")
    nurses = read_csv("nurses.csv")
    nurse_skills = read_csv("nurse_skills.csv")
    coverage = read_csv("coverage_requirements.csv")
    preassignments = read_csv("preassignments.csv")
    incompat = read_csv("incompatibilities.csv")
    charge_rules = read_csv("charge_coverage_rules.csv")
    fairness_rules = read_csv("fairness_rules.csv")
    period_rules = read_csv("period_consecutiveness_rules.csv")
    rest_rules = read_csv("contract_rest_rules.csv")
    dayoff_rules = read_csv("contract_dayoff_rules.csv")
    with open(os.path.join(DATA, "config.json")) as f:
        config = json.load(f)

    W = config["objective_weights"]

    day_list = [r["day"] for r in days]
    day_idx = {r["day"]: int(r["day_index"]) for r in days}
    day_weekend = {r["day"]: int(r["is_weekend"]) for r in days}
    day_sunday = {r["day"]: int(r["is_sunday"]) for r in days}
    day_holiday = {r["day"]: int(r["is_holiday"]) for r in days}
    day_weekday = {r["day"]: r["weekday"] for r in days}
    day_weekend_id = {r["day"]: r["weekend_id"] for r in days}
    D = list(range(1, 32))
    day_by_idx = {int(r["day_index"]): r["day"] for r in days}

    shift_info = {}
    for r in shifts:
        shift_info[r["shift_id"]] = {
            "period": r["period"],
            "start": int(r["start_minute"]),
            "dur": int(r["duration_minutes"]),
            "night": int(r["is_night"]),
        }
    shift_ids = list(shift_info.keys())
    period_of = {s: shift_info[s]["period"] for s in shift_ids}

    contract_info = {}
    for r in contracts:
        ww = set(r["working_weekdays"].split(";")) if r["working_weekdays"] else set()
        contract_info[r["contract_id"]] = {
            "minA": int(r["min_assignments"]),
            "maxA": int(r["max_assignments"]),
            "minW": int(r["min_work_minutes"]),
            "maxW": int(r["max_work_minutes"]),
            "avg": int(r["average_work_minutes"]),
            "ww": ww,
            "maxConsecWork": int(r["max_consecutive_working_days"]),
            "maxConsecOff": int(r["max_consecutive_days_off"]),
            "minRest": int(r["min_rest_minutes"]),
            "maxSundays": int(r["max_sundays"]),
            "maxWeekends": int(r["max_weekends"]),
            "maxHolidays": int(r["max_holidays"]),
            "completeWeekend": int(r["complete_weekend"]),
            "nightGap": int(r["minimum_night_gap_days"]),
        }

    nurse_contract = {r["nurse_id"]: r["contract_id"] for r in nurses}
    nurse_ids = [r["nurse_id"] for r in nurses]

    # eligibility: (n, s, k) -> standard
    elig = {}
    for r in nurse_skills:
        elig[(r["nurse_id"], r["shift_id"], r["skill_id"])] = int(r["standard"])

    # coverage requirements
    cov_req = {}
    for r in coverage:
        cov_req[(r["day"], r["period"], r["skill_id"])] = {
            "min": int(r["min_required"]),
            "opt": int(r["optimal_required"]),
            "max": int(r["max_allowed"]),
        }

    # hard preassignments (all are fixed_status A, hard)
    hard_A = {}
    for r in preassignments:
        if r["assignment_type"] == "fixed_status" and r["hard"] == "1":
            hard_A[(r["nurse_id"], r["day"])] = r["shift_id"] if r["shift_id"] else "A"
        elif r["assignment_type"] == "fixed_shift" and r["hard"] == "1":
            hard_A[(r["nurse_id"], r["day"])] = r["shift_id"]

    # rest rules: min rest after 1 consecutive = 660; after 6 = 2100
    # dayoff: after 6 consecutive counted -> next day off
    # period rules
    period_max_run = {}
    for r in period_rules:
        period_max_run[r["period"]] = int(r["max_consecutive_assignments"])

    # ---- build model ----
    model = Model("nurse_rostering_w7")
    model.setParam("gaprel", 0.0005)
    time_limit = 300.0
    env = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
    if env is not None:
        try:
            time_limit = min(time_limit, float(env))
        except ValueError:
            pass
    model.setParam("limits/time", time_limit)
    model.setMinimize()

    x = {}
    a = {}
    # create variables
    for n in nurse_ids:
        for d in D:
            day = day_by_idx[d]
            if (n, day) in hard_A:
                a[(n, d)] = model.addVar(name=f"a_{n}_{d}", vtype="B", lb=1, ub=1, obj=0.0)
            else:
                a[(n, d)] = model.addVar(name=f"a_{n}_{d}", vtype="B", lb=0, ub=0, obj=0.0)
        for s in shift_ids:
            for k in ["Skill_1", "Skill_2", "Skill_3"]:
                if (n, s, k) in elig:
                    for d in D:
                        day = day_by_idx[d]
                        if (n, day) in hard_A:
                            continue  # fixed A day, no shift
                        x[(n, s, k, d)] = model.addVar(name=f"x_{n}_{s}_{k}_{d}", vtype="B", lb=0, ub=1, obj=0.0)

    # helper: counted assignment indicator for nurse n on day d (shift or A on working weekday)
    def counted_terms(n, d):
        day = day_by_idx[d]
        terms = []
        for (nn, ss, kk, dd), var in x.items():
            if nn == n and dd == d:
                terms.append(var)
        if (n, day) in hard_A:
            ww = contract_info[nurse_contract[n]]["ww"]
            if day_weekday[day] in ww:
                terms.append(a[(n, d)])
        return terms

    # 1) one state per nurse-day
    for n in nurse_ids:
        for d in D:
            day = day_by_idx[d]
            if (n, day) in hard_A:
                continue
            model.addCons(
                quicksum([var for ((nn, ss, kk, dd), var) in x.items() if nn == n and dd == d]) + a[(n, d)] <= 1,
                name=f"onestate_{n}_{d}",
            )

    # 2) coverage
    u_vars = {}
    w_vars = {}
    cov_expr = {}
    for (day, p, k), req in cov_req.items():
        d = day_idx[day]
        expr = quicksum([var for ((nn, ss, kk, dd), var) in x.items() if dd == d and kk == k and period_of[ss] == p])
        cov_expr[(day, p, k)] = expr
        if req["min"] > 0:
            model.addCons(expr >= req["min"], name=f"covmin_{day}_{p}_{k}")
        if req["opt"] > 0:
            u = model.addVar(name=f"u_{day}_{p}_{k}", vtype="C", lb=0, ub=req["opt"], obj=W["understaffing"])
            u_vars[(day, p, k)] = u
            model.addCons(expr + u >= req["opt"], name=f"covopt_{day}_{p}_{k}")
        # excess over max
        if req["max"] < 999:
            w = model.addVar(name=f"w_{day}_{p}_{k}", vtype="C", lb=0, ub=999, obj=W["exceeding_staffing"])
            w_vars[(day, p, k)] = w
            model.addCons(expr <= req["max"] + w, name=f"covmax_{day}_{p}_{k}")

    # 3) contract assignment and work-minute bounds
    for n in nurse_ids:
        c = contract_info[nurse_contract[n]]
        count_expr = quicksum(counted_terms(n, d) for d in D)
        model.addCons(count_expr >= c["minA"], name=f"minA_{n}")
        model.addCons(count_expr <= c["maxA"], name=f"maxA_{n}")
        work_expr = quicksum(
            shift_info[ss]["dur"] * var
            for ((nn, ss, kk, dd), var) in x.items() if nn == n
        )
        a_work = quicksum(
            c["avg"] * a[(n, d)]
            for d in D
            if (n, day_by_idx[d]) in hard_A and day_weekday[day_by_idx[d]] in c["ww"]
        )
        model.addCons(work_expr + a_work >= c["minW"], name=f"minW_{n}")
        model.addCons(work_expr + a_work <= c["maxW"], name=f"maxW_{n}")

    # 4) max consecutive working days (8) and days off (6)
    for n in nurse_ids:
        c = contract_info[nurse_contract[n]]
        Lw = c["maxConsecWork"]
        Lo = c["maxConsecOff"]
        for start in range(1, 32 - Lw + 1):
            window = list(range(start, start + Lw + 1))
            terms = []
            for d in window:
                terms.extend(counted_terms(n, d))
            model.addCons(quicksum(terms) <= Lw, name=f"maxwork_{n}_{start}")
        for start in range(1, 32 - Lo + 1):
            window = list(range(start, start + Lo + 1))
            terms = []
            for d in window:
                terms.extend(counted_terms(n, d))
            model.addCons(quicksum(terms) >= 1, name=f"maxoff_{n}_{start}")

    # 5) rest between consecutive-day detailed shifts (660 min)
    # rest = 1440 - (start_s + dur_s) + start_s' ; forbid if < 660
    forbidden_pairs = set()
    for s1 in shift_ids:
        for s2 in shift_ids:
            rest = 1440 - (shift_info[s1]["start"] + shift_info[s1]["dur"]) + shift_info[s2]["start"]
            if rest < 660:
                forbidden_pairs.add((s1, s2))

    for n in nurse_ids:
        for d in range(1, 31):
            for (s1, s2) in forbidden_pairs:
                terms = []
                for k1 in ["Skill_1", "Skill_2", "Skill_3"]:
                    if (n, s1, k1, d) in x:
                        terms.append(x[(n, s1, k1, d)])
                for k2 in ["Skill_1", "Skill_2", "Skill_3"]:
                    if (n, s2, k2, d + 1) in x:
                        terms.append(x[(n, s2, k2, d + 1)])
                if len(terms) >= 2:
                    # need x1 + x2 <= 1 for every pair (k1,k2)
                    for k1 in ["Skill_1", "Skill_2", "Skill_3"]:
                        if (n, s1, k1, d) not in x:
                            continue
                        for k2 in ["Skill_1", "Skill_2", "Skill_3"]:
                            if (n, s2, k2, d + 1) not in x:
                                continue
                            model.addCons(
                                x[(n, s1, k1, d)] + x[(n, s2, k2, d + 1)] <= 1,
                                name=f"rest_{n}_{d}_{s1}_{s2}_{k1}_{k2}",
                            )

    # 6) 6 consecutive counted -> day d+1 off (no counted) and no detailed shift on d+1
    for n in nurse_ids:
        for d in range(6, 32):
            # window d-5..d
            terms = []
            for i in range(d - 5, d + 1):
                terms.extend(counted_terms(n, i))
            if d + 1 <= 31:
                next_terms = counted_terms(n, d + 1)
                model.addCons(quicksum(terms) + quicksum(next_terms) <= 6, name=f"dayoff6_{n}_{d}")
                # no detailed shift on d+1 if 6 consecutive end at d
                for (nn, ss, kk, dd), var in x.items():
                    if nn == n and dd == d + 1:
                        model.addCons(quicksum(terms) + var <= 6, name=f"recovery_{n}_{d}_{ss}_{kk}")

    # 7) period run-length bounds
    for n in nurse_ids:
        for p, L in period_max_run.items():
            for start in range(1, 32 - L + 1):
                window = list(range(start, start + L + 1))
                terms = []
                for d in window:
                    for (nn, ss, kk, dd), var in x.items():
                        if nn == n and dd == d and period_of[ss] == p:
                            terms.append(var)
                if terms:
                    model.addCons(quicksum(terms) <= L, name=f"periodrun_{n}_{p}_{start}")

    # 8) hard incompatibility: Nurse_3 and Nurse_4 not same detailed shift same day
    for d in D:
        for s in shift_ids:
            for k1 in ["Skill_1", "Skill_2", "Skill_3"]:
                if ("Nurse_3", s, k1, d) in x:
                    for k2 in ["Skill_1", "Skill_2", "Skill_3"]:
                        if ("Nurse_4", s, k2, d) in x:
                            model.addCons(
                                x[("Nurse_3", s, k1, d)] + x[("Nurse_4", s, k2, d)] <= 1,
                                name=f"inc_hard_{d}_{s}_{k1}_{k2}",
                            )

    # 9) soft incompatibilities
    inc_pen_vars = []
    for r in incompat:
        if r["hard"] == "1":
            continue
        na, nb = r["nurse_id_a"], r["nurse_id_b"]
        pen = float(r["penalty"])
        scope = r["scope"]
        sf = r["shift_id"]
        if scope == "same_day":
            for d in D:
                pa = model.addVar(name=f"inc_{na}_{nb}_{d}", vtype="C", lb=0, ub=1, obj=pen * W["incompatibility"])
                inc_pen_vars.append(pa)
                terms_a = [var for ((nn, ss, kk, dd), var) in x.items() if nn == na and dd == d]
                terms_b = [var for ((nn, ss, kk, dd), var) in x.items() if nn == nb and dd == d]
                if terms_a and terms_b:
                    model.addCons(
                        quicksum(terms_a) + quicksum(terms_b) <= 2 - pa,
                        name=f"incsoft_{na}_{nb}_{d}",
                    )
        elif scope == "same_shift":
            shifts_to_check = [sf] if sf else shift_ids
            for d in D:
                for s in shifts_to_check:
                    pa = model.addVar(name=f"inc_{na}_{nb}_{d}_{s}", vtype="C", lb=0, ub=1, obj=pen * W["incompatibility"])
                    inc_pen_vars.append(pa)
                    terms_a = [var for ((nn, ss, kk, dd), var) in x.items() if nn == na and dd == d and ss == s]
                    terms_b = [var for ((nn, ss, kk, dd), var) in x.items() if nn == nb and dd == d and ss == s]
                    if terms_a and terms_b:
                        model.addCons(
                            quicksum(terms_a) + quicksum(terms_b) <= 2 - pa,
                            name=f"incsoft_{na}_{nb}_{d}_{s}",
                        )

    # 10) charge coverage
    charge_pen_vars = []
    for r in charge_rules:
        pool = r["nurse_ids"].split(";")
        pen = float(r["penalty"])
        period = r["period"]
        skill = r["skill_id"]
        scope = r["day_scope"]
        for d in D:
            day = day_by_idx[d]
            if scope == "weekend" and not day_weekend[day]:
                continue
            if scope == "all" or scope == "weekend":
                # staffed indicator: any assignment in period (any skill)
                staffed_terms = [var for ((nn, ss, kk, dd), var) in x.items() if dd == d and period_of[ss] == period]
                pool_terms = [var for ((nn, ss, kk, dd), var) in x.items()
                              if dd == d and period_of[ss] == period and kk == skill and nn in pool]
                if not staffed_terms:
                    continue
                pc = model.addVar(name=f"charge_{r['rule_id']}_{d}", vtype="C", lb=0, ub=1, obj=pen * W["charge_coverage"])
                charge_pen_vars.append(pc)
                # if staffed (sum staffed >= 1), need pool >= 1
                # pc >= 1 - sum(pool) - M*(1 - staffed_bin); use bigM: staffed sum <= 20
                M = 20
                model.addCons(
                    pc >= 1 - quicksum(pool_terms) - M * (1 - quicksum(staffed_terms)),
                    name=f"chargecons_{r['rule_id']}_{d}",
                )

    # 11) fairness
    fair_pen_vars = []
    for r in fairness_rules:
        pool = r["nurse_ids"].split(";")
        pen = float(r["penalty"])
        allowed = int(r["allowed_difference"])
        metric = r["metric"]
        scope = r["day_scope"]
        period = r["period"]
        skill = r["skill_id"]
        # compute per-nurse counts
        nurse_counts = {}
        for n in pool:
            terms = []
            for d in D:
                day = day_by_idx[d]
                if scope == "weekend" and not day_weekend[day]:
                    continue
                if scope == "weekday" and day_weekend[day]:
                    continue
                if metric == "period_assignments":
                    for (nn, ss, kk, dd), var in x.items():
                        if nn == n and dd == d and period_of[ss] == period and kk == skill:
                            terms.append(var)
                elif metric == "counted_assignments":
                    terms.extend(counted_terms(n, d))
            nurse_counts[n] = quicksum(terms) if terms else 0
        pf = model.addVar(name=f"fair_{r['rule_id']}", vtype="C", lb=0, ub=100, obj=pen * W["fairness"])
        fair_pen_vars.append(pf)
        pool_list = list(pool)
        for i in range(len(pool_list)):
            for j in range(i + 1, len(pool_list)):
                ni, nj = pool_list[i], pool_list[j]
                model.addCons(pf >= nurse_counts[ni] - nurse_counts[nj] - allowed, name=f"fair_{r['rule_id']}_{ni}_{nj}_a")
                model.addCons(pf >= nurse_counts[nj] - nurse_counts[ni] - allowed, name=f"fair_{r['rule_id']}_{ni}_{nj}_b")

    # 12) nonstandard penalty in objective
    nonstd_terms = []
    for (n, s, k), std in elig.items():
        if std == 0:
            for d in D:
                if (n, s, k, d) in x:
                    nonstd_terms.append(W["standard_shift"] * x[(n, s, k, d)])

    # objective
    obj_terms = list(nonstd_terms)
    for var in u_vars.values():
        obj_terms.append(var)
    for var in w_vars.values():
        obj_terms.append(var)
    for var in inc_pen_vars:
        obj_terms.append(var)
    for var in charge_pen_vars:
        obj_terms.append(var)
    for var in fair_pen_vars:
        obj_terms.append(var)

    if obj_terms:
        model.setObjective(quicksum(obj_terms), sense="minimize")
    else:
        model.setObjective(0, sense="minimize")

    # ---- solve ----
    status = "unknown"
    obj_val = None
    try:
        model.optimize()
        status = model.getStatus()
        if model.getNSols() > 0:
            obj_val = model.getObjVal()
    except Exception as e:
        print(f"Solver error: {e}")
        status = f"error: {e}"

    # ---- extract solution ----
    solution_rows = []
    one_state_violations = 0
    cov_min_shortfalls = 0

    if model.getNSols() > 0:
        for n in nurse_ids:
            for d in D:
                day = day_by_idx[d]
                states = []
                if (n, day) in hard_A:
                    states.append(("A", ""))
                for s in shift_ids:
                    for k in ["Skill_1", "Skill_2", "Skill_3"]:
                        if (n, s, k, d) in x:
                            val = model.getVal(x[(n, s, k, d)])
                            if val > 0.5:
                                states.append((s, k))
                if len(states) > 1:
                    one_state_violations += 1
                for (sid, kid) in states:
                    solution_rows.append((n, day, sid, kid))

        # coverage validation
        for (day, p, k), req in cov_req.items():
            if req["min"] > 0:
                d = day_idx[day]
                cnt = sum(
                    1
                    for (n2, day2, s2, k2) in solution_rows
                    if day2 == day and k2 == k and period_of.get(s2) == p
                )
                if cnt < req["min"]:
                    cov_min_shortfalls += 1
    else:
        # fallback: emit only hard A rows
        for (n, day), st in hard_A.items():
            solution_rows.append((n, day, "A", ""))

    # write solution
    os.makedirs("/app/submissions", exist_ok=True)
    with open(OUT, "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["nurse_id", "day", "shift_id", "skill_id"])
        for row in sorted(solution_rows, key=lambda r: (r[1], r[0])):
            w.writerow(list(row))

    print(f"Solver status: {status}")
    if obj_val is not None:
        print(f"Objective: {obj_val:.8f}")
    print(f"Wrote {len(solution_rows)} rows to {OUT}")
    print()
    print("--- Validation ---")
    print(f"One-state violations: {one_state_violations}")
    print(f"Coverage min shortfalls: {cov_min_shortfalls}")
    print("Validation complete.")

    # write model.md
    with open(MODEL_MD, "w") as f:
        f.write("# Nurse Rostering Model (W7-01 multi-skill)\n\n")
        f.write("Binary x[n,s,k,d] for eligible (nurse, shift, skill, day); binary a[n,d] for hard fixed status A.\n")
        f.write("Hard: one-state, preassignments, coverage min, contract bounds, consecutive work/off, 660-min rest, 6-consecutive dayoff+recovery, period runs, hard incompatibility.\n")
        f.write("Soft (weighted): understaffing 5, exceeding 10, nonstandard 5, incompatibility, charge coverage, fairness.\n")
        f.write(f"Objective value: {obj_val if obj_val is not None else 'N/A'}\n")

    # write solve_log.md
    with open(LOG_MD, "w") as f:
        f.write("# Solve Log\n\n")
        f.write("Command: `python /app/submissions/solve.py`\n\n")
        f.write(f"SCIP status: {status}\n")
        f.write(f"Objective: {obj_val if obj_val is not None else 'N/A'}\n")
        f.write(f"Time limit: {time_limit}s, gaprel=0.0005\n\n")
        f.write("Validation:\n")
        f.write(f"- One-state violations: {one_state_violations}\n")
        f.write(f"- Coverage min shortfalls: {cov_min_shortfalls}\n")
        f.write(f"- Rows written: {len(solution_rows)}\n")

    model.free()

if __name__ == "__main__":
    main()"}
